mapper.select:
SELECT r.id, r.user_id, r.order_id, r.order_item_id, r.product_id, r.sku_id, r.rating, r.content, r.images, r.is_anonymous, r.status, r.created_at, IF(r.is_anonymous = 1, CONCAT(LEFT(u.nickname, 1), '**'), u.nickname) AS nickname FROM t_review r LEFT JOIN t_user u ON u.id = r.user_id WHERE r.product_id = #{productId} AND r.status = 1
AND r.rating = #{rating}
ORDER BY r.id DESC
